pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(address caller, bytes memory data) public {
        vm.assume(caller != address(0));

        if(data.length == 0) {
            data = abi.encodeWithSignature("noop()");
        }

        vm.deal(caller, 1 ether);

        bool ok;
        try c.Command{value: 0}(address(this), data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
